CREATE TRIGGER "Transaction_validate_insert" BEFORE INSERT ON "Transaction" WHEN NOT (NEW."amount" > 0 AND NEW."amount" <= 2000000000 AND typeof(NEW."amount")='integer' AND NEW."type" IN ('INCOME','EXPENSE','TRANSFER_IN','TRANSFER_OUT','INVESTMENT_IN','INVESTMENT_OUT','INVOICE_PAYMENT','ADJUSTMENT_IN','ADJUSTMENT_OUT') AND NEW."status" IN ('PLANNED','CONFIRMED')) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "Transaction_validate_update" BEFORE UPDATE ON "Transaction" WHEN NOT (NEW."amount" > 0 AND NEW."amount" <= 2000000000 AND typeof(NEW."amount")='integer' AND NEW."type" IN ('INCOME','EXPENSE','TRANSFER_IN','TRANSFER_OUT','INVESTMENT_IN','INVESTMENT_OUT','INVOICE_PAYMENT','ADJUSTMENT_IN','ADJUSTMENT_OUT') AND NEW."status" IN ('PLANNED','CONFIRMED')) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CardPurchase_validate_insert" BEFORE INSERT ON "CardPurchase" WHEN NOT (NEW."amount" > 0 AND typeof(NEW."amount")='integer' ) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CardPurchase_validate_update" BEFORE UPDATE ON "CardPurchase" WHEN NOT (NEW."amount" > 0 AND typeof(NEW."amount")='integer' ) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CardInstallment_validate_insert" BEFORE INSERT ON "CardInstallment" WHEN NOT (NEW."amount" > 0 AND typeof(NEW."amount")='integer' AND NEW."number">0) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CardInstallment_validate_update" BEFORE UPDATE ON "CardInstallment" WHEN NOT (NEW."amount" > 0 AND typeof(NEW."amount")='integer' AND NEW."number">0) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "InvoicePayment_validate_insert" BEFORE INSERT ON "InvoicePayment" WHEN NOT (NEW."amount" > 0 AND typeof(NEW."amount")='integer' ) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "InvoicePayment_validate_update" BEFORE UPDATE ON "InvoicePayment" WHEN NOT (NEW."amount" > 0 AND typeof(NEW."amount")='integer' ) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "InvestmentOperation_validate_insert" BEFORE INSERT ON "InvestmentOperation" WHEN NOT (NEW."amount" > 0 AND NEW."costBasis">=0 AND NEW."position">0 AND NEW."type" IN ('DEPOSIT','WITHDRAW')) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "InvestmentOperation_validate_update" BEFORE UPDATE ON "InvestmentOperation" WHEN NOT (NEW."amount" > 0 AND NEW."costBasis">=0 AND NEW."position">0 AND NEW."type" IN ('DEPOSIT','WITHDRAW')) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "InvestmentValuation_validate_insert" BEFORE INSERT ON "InvestmentValuation" WHEN NOT (NEW."amount" >= 0 AND typeof(NEW."amount")='integer' AND NEW."operationCount">=0) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "InvestmentValuation_validate_update" BEFORE UPDATE ON "InvestmentValuation" WHEN NOT (NEW."amount" >= 0 AND typeof(NEW."amount")='integer' AND NEW."operationCount">=0) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CategoryBudget_validate_insert" BEFORE INSERT ON "CategoryBudget" WHEN NOT (NEW."amount">0 AND typeof(NEW."amount")='integer' ) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CategoryBudget_validate_update" BEFORE UPDATE ON "CategoryBudget" WHEN NOT (NEW."amount">0 AND typeof(NEW."amount")='integer' ) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CreditCard_validate_insert" BEFORE INSERT ON "CreditCard" WHEN NOT (NEW."limit">0 AND NEW."closingDay" BETWEEN 1 AND 31 AND NEW."dueDay" BETWEEN 1 AND 31) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "CreditCard_validate_update" BEFORE UPDATE ON "CreditCard" WHEN NOT (NEW."limit">0 AND NEW."closingDay" BETWEEN 1 AND 31 AND NEW."dueDay" BETWEEN 1 AND 31) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "Category_validate_insert" BEFORE INSERT ON "Category" WHEN NOT (NEW."type" IN ('INCOME','EXPENSE') AND (NEW."parentId" IS NULL OR NEW."parentId" != NEW."id")) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "Category_validate_update" BEFORE UPDATE ON "Category" WHEN NOT (NEW."type" IN ('INCOME','EXPENSE') AND (NEW."parentId" IS NULL OR NEW."parentId" != NEW."id")) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "Account_validate_insert" BEFORE INSERT ON "Account" WHEN NOT (typeof(NEW."initialBalance")='integer' AND NEW."type" IN ('CHECKING','SAVINGS','CASH','OTHER')) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
CREATE TRIGGER "Account_validate_update" BEFORE UPDATE ON "Account" WHEN NOT (typeof(NEW."initialBalance")='integer' AND NEW."type" IN ('CHECKING','SAVINGS','CASH','OTHER')) BEGIN SELECT RAISE(ABORT, 'Invalid financial record'); END;
